// Bug: the list can change while a picked file is still being read (a second, smaller file finishes first, or the customer
// adds a todo). When the first file finishes, the import must still ask before replacing a non-empty list.
// Drives app/app.js unchanged in a vm with a fake page, like tests/app.test.js. Run: node --test
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const crypto = require('node:crypto');
const backup = require('../app/backup.js');

const appJs = fs.readFileSync(path.join(__dirname, '..', 'app', 'app.js'), 'utf8');

const todo = (id) => ({ id, title: `Việc ${id}`, done: false, createdAt: 1 });
const fileOf = (todos) => JSON.stringify({ version: 1, todos });
const settle = () => new Promise((r) => setImmediate(r));

function fakeElement() {
  const listeners = {};
  const el = {
    textContent: '', innerHTML: '', hidden: false, value: '', className: '', dataset: {}, returnValue: '',
    append() {},
    querySelector(sel) { return (el.children[sel] ||= fakeElement()); },
    addEventListener(type, fn) { (listeners[type] ||= []).push(fn); },
    fire(type) { const fns = listeners[type] || []; listeners[type] = []; fns.forEach((fn) => fn()); },
    children: {},
  };
  return el;
}

// A file whose text() resolves only when the test calls finish().
function slowFile(text) {
  let finish;
  const pending = new Promise((r) => { finish = () => r(text); });
  return { size: Buffer.byteLength(text), text: () => pending, finish };
}

function quickFile(text) {
  return { size: Buffer.byteLength(text), text: async () => text };
}

// Empty, readable list. Every confirm dialog is answered "Huỷ" (cancel); `asked` records each question.
function loadApp() {
  const elements = {};
  const replaced = [];
  const asked = [];
  const store = {
    readError: false,
    load() { return { todos: [], readError: false }; },
    save() { return 'saved'; },
    replace(todos) { replaced.push(todos.map((t) => t.id)); return 'saved'; },
  };
  const document = {
    querySelector(sel) { return (elements[sel] ||= fakeElement()); },
    querySelectorAll() { return []; },
    createElement() { return fakeElement(); },
  };
  const dialog = document.querySelector('#confirm');
  dialog.showModal = () => {
    asked.push(document.querySelector('#confirm-text').textContent);
    setImmediate(() => { dialog.returnValue = ''; dialog.fire('close'); });
  };
  vm.runInNewContext(appJs, { ...backup, store, document, crypto, setImmediate });
  const pick = (file) => {
    const input = document.querySelector('#import');
    input.files = [file];
    return input.onchange({ target: input });
  };
  const submit = (value) => {
    document.querySelector('#title').value = value;
    document.querySelector('#add').onsubmit({ preventDefault() {} });
  };
  return { pick, submit, replaced, asked };
}

test('a second, smaller file that finishes first: the first file asks before replacing it', async () => {
  const { pick, replaced, asked } = loadApp();
  const big = slowFile(fileOf([todo('a1'), todo('a2'), todo('a3')]));
  const first = pick(big);
  await pick(quickFile(fileOf([todo('b1')])));
  assert.deepEqual(replaced, [['b1']], 'the small file fills the empty list without asking');
  assert.equal(asked.length, 0);

  big.finish();
  await first;
  assert.equal(asked.length, 1, 'the first file must ask before replacing the 1 todo now on screen');
  assert.deepEqual(replaced, [['b1']], 'cancel keeps the list from the small file');
});

test('a todo added while the file is being read: the import asks before replacing it', async () => {
  const { pick, submit, replaced, asked } = loadApp();
  const file = slowFile(fileOf([todo('a1'), todo('a2')]));
  const importing = pick(file);
  submit('Mua sữa');

  file.finish();
  await importing;
  await settle();
  assert.equal(asked.length, 1, 'must ask before replacing the todo added while reading');
  assert.deepEqual(replaced, [], 'cancel writes nothing');
});

